entries[36954] = { ["name"] = "Dimensionszerfetzer: Area 52", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Urfeuer (2), Die Größere (2), Eine Handvoll Teufelseisenbolzen (4), Khoriumkraftkern\nBeruf:\nIngenieurskunst der Scherbenwelt (50)\nSpezialisierung:\nGobliningenieurskunst\nZone:\nNethersturm\nNSC:\nKablamm Weitschleuder\n\nDimensionszerfetzer: Area 52\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Zerreißt die Dimensionsschranken, um Euch nach Area 52 im Nethersturm zu transportieren. Manchmal können dabei zwar technische Probleme auftreten, aber das ist ja das Spannende an der Gobliningenieurskunst! (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt\n(50)\nBenötigt Gobliningenieur" }
entries[36955] = { ["name"] = "Extrem sicherer Transporter: Toshleys Station", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Urluft (2), Teufelsstahlstabilisator (2), Eine Handvoll Teufelseisenbolzen (4), Khoriumkraftkern\nBeruf:\nIngenieurskunst der Scherbenwelt (50)\nSpezialisierung:\nGnomeningenieurskunst\nZone:\nSchergrat\nNSC:\nSmiles O'Byron\n\nExtrem sicherer Transporter: Toshleys Station\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Transportiert Euch sicher zu Toshleys Station am Schergrat! Es gibt nichts, worum man sich bei der Benutzung dieses Geräts sorgen müsste! Dank der gnomischen Ingenieurskunst kommt jeder schnell und zuverlässig ans Ziel! (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt\n(50)\nBenötigt Gnomeningenieur" }
